def get_multiminute_his_data(symbols, count, query_date, frequency=Frequency.DAILY.value, fields=None, fq=None, skip_suspended=False, include=False, execution_date=None, asset=None, dividends_all=None):
    _query_date = query_date // 100
    _min_datetime = _query_date // 10000 * 10000 + 930
    his_data_dict = OrderedDict()
    if include and _query_date > _min_datetime:
        count_min = 0
        query_time = str(query_date)
        if int(query_time[8:12]) <= 1130:
            minute_c = int((datetime.datetime.strptime(query_time, '%Y%m%d%H%M%S') - datetime.datetime.strptime(query_time[0:8] + '093000', '%Y%m%d%H%M%S')).seconds / 60)
            count_min = minute_c % int(frequency[:-1])
        elif int(query_time[8:12]) <= 1500:
            minute_c = int((datetime.datetime.strptime(query_time, '%Y%m%d%H%M%S') - datetime.datetime.strptime(query_time[0:8] + '130000', '%Y%m%d%H%M%S')).seconds / 60)
            count_min = minute_c % int(frequency[:-1])
        if count_min == 0:
            his_data_dict = get_kline_by_count_new(symbols, count, query_date, frequency, fields, fq, include, execution_date, asset, dividends_all)
            if len(his_data_dict) == 0:
                return his_data_dict
        else:
            add_fre_minute_time = datetime.datetime.strptime(query_time, '%Y%m%d%H%M%S') + datetime.timedelta(minutes=int(frequency[:-1]))
            fix_query_date = int(datetime.datetime.strftime(add_fre_minute_time, '%Y%m%d%H%M%S'))
            need_exrights = 0
            dividends_stock = []
            tmp_fields = CAL_EXRIGHTS_COLUMNS
            if fq is not None and dividends_all is not None and isinstance(fields, str) and fields not in tmp_fields or isinstance(fields, list):
                if len(set(fields).intersection(set(tmp_fields))) == 0:
                    need_exrights = 0
                elif fq in DIVIDEND_CALC_TYPE:
                    dividends_stock = dividends_all.keys()
                    need_exrights = 1
            start_000300, end_000300 = get_benchmark_datetime(count, fix_query_date, frequency, fields, include, execution_date)
            if not start_000300 is not None or end_000300 is None:
                return OrderedDict()
            else:
                for symbol in symbols:
                    asset_one = asset[symbol]
                    stock = symbol.replace('SS', 'XSHG').replace('SZ', 'XSHE')
                    need_exrights_one = 0
                    dividends = None
                    if need_exrights == 1:
                        if stock not in dividends_stock:
                            need_exrights_one = 0
                            dividends = None
                        else:
                            need_exrights_one = need_exrights
                            dividends = dividends_all[stock]
                    his_data_fix = get_kline_by_count(symbol, count, fix_query_date, frequency, None, fq, include, execution_date, asset_one, need_exrights_one, dividends, start_000300, end_000300)
                    if len(his_data_fix) == 0:
                        his_data_dict[symbol] = his_data_fix[fields]
                        continue
                    elif len(his_data_fix) < count:
                        if his_data_fix['datetime'][-1] < query_date:
                            his_data_dict[symbol] = his_data_fix[fields]
                            continue
                        fix_data = get_kline_by_count(symbol, count_min, query_date, '1m', None, fq, include, execution_date, asset_one, need_exrights_one, dividends)
                        if len(fix_data) == 0:
                            his_data_dict[symbol] = his_data_fix[fields]
                            continue
                        his_data_fix['open'][-1] = fix_data['open'][0].copy()
                        his_data_fix['high'][-1] = fix_data['high'].max().copy()
                        his_data_fix['low'][-1] = fix_data['low'].min().copy()
                        his_data_fix['close'][-1] = fix_data['close'][-1].copy()
                        his_data_fix['volume'][-1] = fix_data['volume'].sum().copy()
                        his_data_fix['money'][-1] = fix_data['money'].sum().copy()
                        his_data_fix['price'][-1] = fix_data['price'][-1].copy()
                        his_data_dict[symbol] = his_data_fix[fields]
                        continue
                    else:
                        fix_data = get_kline_by_count(symbol, count_min, query_date, '1m', None, fq, include, execution_date, asset_one, need_exrights_one, dividends)
        return his_data_dict
def get_multiminute_his_data_by_date(symbols, start_date, end_date, frequency=Frequency.DAILY.value, fields=None, fq=None, asset=None, dividends_all=None):
    his_data_dict = OrderedDict()
    count_min = 0
    if asset[symbols[0]].get('type', '') == 'FUTURE':
        _end_time = end_date // 100
        min_datetime = int(str(end_date // 1000000) + '0800')
        _1m_df_nan_data, _ = get_kline_time_by_asset('1m', _end_time, asset['trading_time'])
        _1m_df_nan_data = _1m_df_nan_data[_1m_df_nan_data['datetime'] > min_datetime]
        _df_nan_data, _ = get_kline_time_by_asset(frequency, _end_time, asset['trading_time'])
        datetime_1m_list = _1m_df_nan_data['datetime'].tolist()
        if _end_time in datetime_1m_list and _end_time not in _df_nan_data['datetime'].tolist():
            index = _df_nan_data['datetime']
            left = index.tolist()[int(index.searchsorted(_end_time)) - 1]
            right = index.tolist()[int(index.searchsorted(_end_time))]
            count_min = len(_1m_df_nan_data.loc[(_1m_df_nan_data['datetime'] > left) & (_1m_df_nan_data['datetime'] <= _end_time)])
            _last_timestamp = right
    else:
        now_date = end_date // 1000000
        min_datetime = now_date * 1000000 + 93000
        am_close_market_datetime = now_date * 1000000 + 113000
        pm_open_market_datetime = now_date * 1000000 + 130000
        pm_close_market_datetime = now_date * 1000000 + 150000
        time_count = 0
        _end_time = 930
        if end_date > min_datetime:
            if pm_open_market_datetime > end_date > am_close_market_datetime:
                _end_time = am_close_market_datetime
            elif end_date > pm_close_market_datetime:
                _end_time = pm_close_market_datetime
            else:
                _end_time = end_date
            time_count = int((convert_int_to_datetime(_end_time) - convert_int_to_datetime(min_datetime)).seconds / 60)
        if _end_time >= pm_open_market_datetime:
            time_count -= 90
        count_min = time_count % int(frequency[:-1])
        _last_timestamp = int(datetime.datetime.strftime(datetime.datetime.strptime(str(_end_time // 100), '%Y%m%d%H%M') + datetime.timedelta(minutes=int(frequency[:-1]) - count_min), '%Y%m%d%H%M'))
    if count_min == 0:
        his_data_dict = get_kline_by_date_new(symbols, start_date, end_date, frequency, fields, fq, asset, dividends_all)
    else:
        need_exrights = 0
        dividends_stock = []
        tmp_fields = CAL_EXRIGHTS_COLUMNS
        if fq is not None and dividends_all is not None and isinstance(fields, str) and fields not in tmp_fields or isinstance(fields, list):
            if len(set(fields).intersection(set(tmp_fields))) == 0:
                need_exrights = 0
            elif fq in DIVIDEND_CALC_TYPE:
                dividends_stock = dividends_all.keys()
                need_exrights = 1
        for symbol in symbols:
            asset_one = asset[symbol]
            stock = symbol.replace('SS', 'XSHG').replace('SZ', 'XSHE')
            need_exrights_one = 0
            dividends = None
            if need_exrights == 1:
                if stock not in dividends_stock:
                    need_exrights_one = 0
                    dividends = None
                else:
                    need_exrights_one = need_exrights
                    dividends = dividends_all[stock]
            add_fre_minute_time = datetime.datetime.strptime(str(end_date), '%Y%m%d%H%M%S') + datetime.timedelta(minutes=int(frequency[:-1]))
            fix_query_date = int(datetime.datetime.strftime(add_fre_minute_time, '%Y%m%d%H%M%S'))
            his_data = get_kline_by_date_one(symbol, start_date, fix_query_date, frequency, None, fq, asset_one, need_exrights_one, dividends)
            if len(his_data) == 0:
                his_data_dict[symbol] = his_data[fields]
                continue
            _last_kline = get_kline_by_count(symbol, count_min, end_date, '1m', None, fq, True, execution_date=None, asset=asset_one, need_exrights=need_exrights_one, dividends=dividends)
            if not len(his_data) == 0:
                if his_data['datetime'][-1] != _last_timestamp:
                    his_data_dict[symbol] = his_data[fields]
                    continue
                elif len(_last_kline) > 0:
                    his_data['open'][-1] = _last_kline['open'][0].copy()
                    his_data['high'][-1] = _last_kline['high'].max().copy()
                    his_data['low'][-1] = _last_kline['low'].min().copy()
                    his_data['close'][-1] = _last_kline['close'][-1].copy()
                    his_data['volume'][-1] = _last_kline['volume'].sum().copy()
                    his_data['money'][-1] = _last_kline['money'].sum().copy()
                    his_data['price'][-1] = _last_kline['price'][-1].copy()
                    his_data_dict[symbol] = his_data[fields]
                continue
    return his_data_dict
def kline_datetime_list(count, query_date, frequency, include=False, bussiness_type='STOCK'):
    now_date = int(time.strftime('%Y%m%d'))
    am_open_datetime = now_date * 10000 + 930
    am_close_datetime = now_date * 10000 + 1130
    pm_open_datetime = now_date * 10000 + 1300
    pm_close_datetime = now_date * 10000 + 1500
    if bussiness_type == 'HKS':
        am_close_datetime = now_date * 10000 + 1200
        pm_close_datetime = now_date * 10000 + 1600
    max_len_real_data = -1
    df_nan_data = None
    if frequency.find(Frequency.DAILY.value) > -1:
        df_nan_data = get_kline_time_by_frequency_array(frequency, query_date, bussiness_type)
    elif frequency[-1] == Frequency.MINUTE.value[-1]:
        if pm_open_datetime > query_date > am_close_datetime:
            _end_time = am_close_datetime
        elif query_date > pm_close_datetime:
            _end_time = pm_close_datetime
        else:
            _end_time = query_date
        time_count = int((convert_int_to_datetime(_end_time) - convert_int_to_datetime(am_open_datetime)).seconds / 60)
        if query_date >= pm_open_datetime:
            time_count -= 90
        if not include and frequency == Frequency.MINUTE.value and query_date not in (am_open_datetime, pm_open_datetime):
            if pm_open_datetime > query_date > am_close_datetime or query_date > pm_close_datetime:
                min_datetime = am_open_datetime
                if frequency == Frequency.MINUTE.value:
                    max_len_real_data = time_count
                    min_count = max_len_real_data
                    if max_len_real_data > count:
                        min_count = count
                        tmp_end_datetime = query_date
                        if tmp_end_datetime > pm_close_datetime:
                            tmp_end_datetime = pm_close_datetime
                        if am_close_datetime < tmp_end_datetime <= pm_open_datetime:
                            pass
                        tmp_end_datetime = am_close_datetime
                        if not include:
                            min_count -= 1
                        min_datetime = change_dt_2_int(convert_int_to_datetime(tmp_end_datetime) - datetime.timedelta(minutes=min_count), frequency)
                        if tmp_end_datetime >= pm_open_datetime and min_datetime <= pm_open_datetime:
                            min_datetime = change_dt_2_int(convert_int_to_datetime(min_datetime) - datetime.timedelta(minutes=90), frequency)
                    _df_nan_data = get_kline_time_by_frequency_array(frequency, query_date, bussiness_type)
                    if not include:
                        if query_date <= pm_close_datetime:
                            df_nan_data = _df_nan_data[(_df_nan_data['datetime'] >= min_datetime) & (_df_nan_data['datetime'] < query_date)]
                        else:
                            df_nan_data = _df_nan_data[(_df_nan_data['datetime'] > min_datetime) & (_df_nan_data['datetime'] <= query_date)]
                elif FREQUENCY_TO_COUNT[frequency] >= 5:
                    max_len_real_data = ceil(time_count / FREQUENCY_TO_COUNT[frequency])
                    if not include and query_date != pm_open_datetime:
                        if pm_open_datetime > query_date > am_close_datetime or query_date > pm_open_datetime:
                            max_len_real_data = count if max_len_real_data > count else max_len_real_data
                        max_len_real_data -= 1
                    max_len_real_data = 0 if max_len_real_data < 0 else max_len_real_data
                    max_datetime = change_dt_2_int(convert_int_to_datetime(query_date) + datetime.timedelta(minutes=int(frequency[:-1])), frequency)
                    _df_nan_data = get_kline_time_by_frequency_array(frequency, query_date, bussiness_type)
                    if not include:
                        if query_date <= pm_close_datetime:
                            df_nan_data = _df_nan_data[_df_nan_data['datetime'] < query_date]
                        else:
                            df_nan_data = _df_nan_data[_df_nan_data['datetime'] < max_datetime]
                    df_nan_data = df_nan_data[-max_len_real_data:]
            time_count -= 1
    return df_nan_data
def get_exrights_data(bars_ndarr, symbol, frequency, fq, dividend_dict, query_date=None, execution_date=None):
    index = bars_ndarr[BarDataEnum.DATETIME.value]
    base_bars = np.empty(shape=(len(index), len(bars_ndarr.dtype)), dtype=np.float64)
    bars_ndarr_list = bars_ndarr.tolist()
    for i in range(len(index)):
        base_bars[i] = bars_ndarr_list[i]
    exright_save_digits = save_digits
    if symbol[0] in special_stock_first:
        exright_save_digits = special_save_digits
    if fq == 'dypre':
        dividend_date_list = list(dividend_dict.keys())
        dividend_date_list.sort()
        if frequency in Minute_Frequency:
            query_date = int(str(query_date)[0:8])
        if frequency == '1d' and execution_date is not None:
            query_date = execution_date
        if len(dividend_date_list) >= 1 and query_date >= dividend_date_list[-1]:
            adjust_bars_tuple = CalExrights(base_bars, index, dividend_dict, 'pre', exright_save_digits)
        else:
            index_list = list(index)
            index_list.append(query_date)
            index_new = np.array(index_list)
            adjust_bars_tuple = CalExrights(base_bars, index_new, dividend_dict, fq, exright_save_digits)
    elif fq == 'price_dypre':
        dividend_date_list = list(dividend_dict.keys())
        dividend_date_list.sort()
        if all_backtest_date is None:
            strategy_log.warning('获取回测日期为None，请检查是否多线程调用取数接口或数据异常。')
            return bars_ndarr
        elif len(dividend_date_list) >= 1 and all_backtest_date >= dividend_date_list[-1]:
            adjust_bars_tuple = CalExrights(base_bars, index, dividend_dict, 'pre', exright_save_digits)
        else:
            index_list = list(index)
            index_list.append(all_backtest_date)
            index_new = np.array(index_list)
            adjust_bars_tuple = CalExrights(base_bars, index_new, dividend_dict, 'dypre', exright_save_digits)
    else:
        adjust_bars_tuple = CalExrights(base_bars, index, dividend_dict, fq, exright_save_digits)
    adjust_bars = adjust_bars_tuple[0]
    real_data_tmp = np.array([tuple(_d) for _d in adjust_bars], dtype=bars_ndarr.dtype)
    return real_data_tmp
def deal_hq_list_to_cacahe(list_index_data):
    """
    将行情数据列表转换为缓存数据列表。

    :param list_index_data: 行情数据列表，包含日期、开盘价、最高价、最低价、收盘价、成交量、成交额、前收盘价、涨停价、跌停价等字段。

    :returns list: 转换后的缓存数据列表。
    """
    list_new_data = list()
    list_new_data.append(list_index_data[0])
    list_new_data.append(list_index_data[1])
    list_new_data.append(list_index_data[4])
    list_new_data.append(list_index_data[2])
    list_new_data.append(list_index_data[3])
    list_new_data.append(list_index_data[5])
    list_new_data.append(list_index_data[6])
    list_new_data.append(0)
    list_new_data.append(list_index_data[7])
    list_new_data.append(list_index_data[8])
    list_new_data.append(list_index_data[9])
    list_new_data.append(0)
    list_new_data.append(list_index_data[4])
    return list_new_data
def get_kline_by_date_ndarray(symbol, frequency_int, kline_ndarray, df_date_list_len):
    """
    根据股票代码、频率和日期范围从行情API在线请求获取K线数据，并更新传入的ndarray。

    :param symbol: 股票代码。
    :param frequency_int: K线频率（例如1表示1分钟K线）。
    :param kline_ndarray: 存储K线数据的ndarray。
    :param df_date_list_len: K线数据日期列表的长度。

    :return numpy.ndarray: 更新后的K线数据ndarray。
    """
    symbol = symbol.replace('.XSHE', '.SZ').replace('.XSHG', '.SS')
    curr_date = str(datetime.datetime.now().strftime('%Y%m%d'))
    params = str(['kline', symbol, frequency_int, curr_date, curr_date])
    try:
        redata, flag = api_get_from_zeromq(params)
        count = 0
        while not redata and count < 2:
            time.sleep(1)
            if flag == 1:
                system_log.debug('获取K线数据异常，现在进行第{}次重试'.format(str(count + 1)))
            elif flag == -1:
                system_log.debug('获取K线数据返回为空，现在进行第{}次重试'.format(str(count + 1)))
            redata, flag = api_get_from_zeromq(params)
            count += 1
        if redata:
            for i in not redata and count < 2:
                if df_date_list[i] in list_data_date:
                    datetime_index = list_data_date.index(df_date_list[i])
                    list_index_data = list_data[datetime_index]
                    list_new_data = deal_hq_list_to_cacahe(list_index_data)
                    kline_ndarray[i] = tuple(list_new_data)
            else:
                return kline_ndarray
        elif flag == 1:
            system_log.debug('K线数据转化异常，默认返回空值')
        elif flag == -1:
            system_log.debug('K线数据返回空值')
    except Exception as e:
        system_log.debug('K线数据获取失败, 异常：{}'.format(e))
    return kline_ndarray
