def stk_resample_days_orderddict(order_dict_data, fields, frequency, count):
    """
    股票类型
    将日线数据合并成周线数据
    :param order_dict_data: OrderedDict,根据时间查询出来的日线数据；
    :param fields: list 需要的字段
    :param fields: frequency 频率周期
    :param count: int 统计的频率的数量
    :return OrderedDict
    """
    np_dict = OrderedDict()
    if len(order_dict_data) == 0:
        return order_dict_data
    else:
        field_ori = fields
        if isinstance(fields, six.string_types):
            field_ori = [fields]
        for security, data in order_dict_data.items():
            df = pd.DataFrame(data)
            dates = pd.to_datetime(df['datetime'], format='%Y%m%d').tolist()
            n = df.iloc[:, 0].size
            datas_list = []
            datas_index = []
            j = (i := 0)
            while j < n:
                if _is_same_type_date(dates[i], dates[j], frequency):
                    datas_index.append(j)
                    i = j
                    j += 1
                else:
                    datas_list.append(copy.deepcopy(datas_index))
                    datas_index = []
                    i = j
            if j == n:
                datas_list.append(copy.deepcopy(datas_index))
            count = count if count else 0
            i = 0
            result = pd.DataFrame(columns=['datetime', 'open', 'high', 'low', 'close', 'volume', 'money', 'price'])
            for datas in datas_list[-count:]:
                if not datas:
                    continue
                result.loc[i] = {'datetime': data['datetime'][datas[-1]], 'open': data['open'][datas[0]], 'high': data['high'][datas].max(), 'low': data['low'][datas].min(), 'close': data['close'][datas[-1]], 'volume': data['volume'][datas[0]:datas[-1] + 1].sum(), 'money': data['money'][datas[0]:datas[-1] + 1].sum(), 'price': data['price'][datas[-1]]}
                i += 1
            result.set_index('datetime', inplace=True)
            np_array = np.array(result.to_records(), dtype=data.dtype)
            if field_ori is None:
                np_dict[security] = np_array
                continue
            elif isinstance(field_ori, list):
                np_dict[security] = np_array[field_ori]
        else:
            return np_dict
def _is_same_type_date(day1, day2, frequency):
    if frequency == '1w':
        a = day1.isocalendar()
        b = day2.isocalendar()
        if a[0] == b[0] and a[1] == b[1]:
            return True
        return False
    elif frequency == 'mo':
        if day1.year == day2.year and day1.month == day2.month:
            return True
        else:
            return False
    elif frequency == '1y':
        if day1.year == day2.year:
            return True
        else:
            return False
    elif frequency == '1q':
        if day1.year == day2.year and (day1.month - 1) // 3 == (day2.month - 1) // 3:
            return True
        else:
            return False
