def np_tp_pd(nd_array_or_dict, field_ori, is_string, index_t=None, bench_type=None):
    if len(nd_array_or_dict) == 0:
        return pd.DataFrame()
    elif 'datetime' in field_ori:
        field_ori.remove('datetime')
    if is_string:
        for security, nd_array in nd_array_or_dict.items():
            t = tuple(nd_array['datetime'])
            return pd.DataFrame(SymbolDF(nd_array[field_ori], index=nd_array_to_datetime_index(t)))
    else:
        bench_tuple = ()
        for d_count in range(len(bench_type)):
            if d_count == 0:
                continue
            elif bench_type[d_count] == np.int64:
                bench_tuple += (0,)
                continue
            else:
                bench_tuple += (np.nan,)
                continue
        bench_len = len(index_t)
        field_data_dict = {'code': []}
        for field in field_ori:
            field_data_dict[field] = []
        dates = []
        for security, nd_array in nd_array_or_dict.items():
            nd_array = _align_data_to_benchmark(nd_array, index_t, bench_tuple, bench_len, security)
            dates.extend(nd_array['datetime'])
            field_data_dict['code'].extend([security] * len(nd_array))
            for field in field_ori:
                field_data_dict[field].extend(nd_array[field])
        else:
            pd_all_array = pd.DataFrame(field_data_dict, index=nd_array_to_datetime_index(tuple(dates)))
            return pd_all_array
def _align_data_to_benchmark(nd_array, index_t, bench_tuple, bench_len, security):
    """
    将股票数据对齐到基准时间轴

    :param nd_array: 原始数据数组
    :param index_t: 基准时间轴
    :param bench_tuple: 基准填充元组
    :param bench_len: 基准长度
    :param security: 股票代码
    
    :return array: 对齐后的数据数组
    """
    t = nd_array['datetime']
    if len(nd_array) < bench_len:
        aligned_nd_array = np.full(shape=bench_len, fill_value=np.nan, dtype=nd_array.dtype)
        date_to_index = {date: idx for idx, date in enumerate(t)}
        for i, bench_date in enumerate(index_t):
            if bench_date in date_to_index:
                aligned_nd_array[i] = nd_array[date_to_index[bench_date]]
                continue
            aligned_nd_array[i] = (bench_date,) + bench_tuple
            continue
        else:
            return aligned_nd_array
    elif len(nd_array) > bench_len:
        system_log.error('代码{} 获取根数超过000300模板代码的数据根数, 获取数据为{}'.format(security, nd_array))
        aligned_nd_array = np.full(shape=bench_len, fill_value=np.nan, dtype=nd_array.dtype)
        date_to_index = {date: idx for idx, date in enumerate(t)}
        for i, bench_date in enumerate(index_t):
            if bench_date in date_to_index:
                aligned_nd_array[i] = nd_array[date_to_index[bench_date]]
                continue
            aligned_nd_array[i] = (bench_date,) + bench_tuple
            continue
        else:
            return aligned_nd_array
    else:
        return nd_array
